/**
 * Sidebar for the UFLinux documentation site.
 *
 * Labels are given in English (the root locale) with Czech in `translations`.
 * Pages are listed explicitly rather than autogenerated so that both locales get
 * the same navigation: untranslated pages fall back to the English content.
 */

const cs = (/** @type {string} */ text) => ({ cs: text });

/** @param {{ label: string, cs: string, slug: string }} page */
function page({ label, cs: czech, slug }) {
	return { label, translations: cs(czech), slug };
}

